static snmp_err_t phasestatusgrouptable_get_instance(const u32_t *column,
                                                     const u32_t *row_oid,
                                                     u8_t row_oid_len,
                                                     struct snmp_node_instance *
                                                     cell_instance)
{
  u8_t i;

  LWIP_UNUSED_ARG(column);

  /* check if incoming OID length and if values are in plausible range */
  if (!snmp_oid_in_range(row_oid,
                         row_oid_len,
                         phase_status_group_table_oid_ranges,
                         LWIP_ARRAYSIZE(phase_status_group_table_oid_ranges)))
  {
    return SNMP_ERR_NOSUCHINSTANCE;
  }

  /* get netif index from incoming OID */
  i = row_oid[0];

  /* find netif with index */
  if (i <= PHASE_STATUS_GROUPS_MAX)
  {
    cell_instance->reference.u32 = (u32_t) (i);

    return SNMP_ERR_NOERROR;
  }

  return SNMP_ERR_NOSUCHINSTANCE;
}

static snmp_err_t phasestatusgrouptable_get_next_instance(const u32_t *column,
                                                          struct snmp_obj_id *
                                                          row_oid,
                                                          struct
                                                          snmp_node_instance *
                                                          cell_instance)
{
  struct snmp_next_oid_state state;
  u32_t result_temp[LWIP_ARRAYSIZE(phase_status_group_table_oid_ranges)];
  size_t i;

  LWIP_UNUSED_ARG(column);

  /* init struct to search next oid */
  snmp_next_oid_init(&state, row_oid->id, row_oid->len, result_temp,
                     LWIP_ARRAYSIZE(phase_status_group_table_oid_ranges));

  /* iterate over all possible OIDs to find the next one */
  for (i = 1; i <= PHASE_STATUS_GROUPS_MAX; i++)
  {
    u32_t test_oid[LWIP_ARRAYSIZE(phase_status_group_table_oid_ranges)];

    test_oid[0] = i;

    /* check generated OID: is it a candidate for the next one? */
    snmp_next_oid_check(&state, test_oid,
                        LWIP_ARRAYSIZE(phase_status_group_table_oid_ranges),
                        (void *) i);
  }

  /* did we find a next one? */
  if (state.status == SNMP_NEXT_OID_STATUS_SUCCESS)
  {
    snmp_oid_assign(row_oid, state.next_oid, state.next_oid_len);
    cell_instance->reference.u32 = LWIP_CONST_CAST(u32_t, state.reference);

    return SNMP_ERR_NOERROR;
  }

  /* not found */
  return SNMP_ERR_NOSUCHINSTANCE;
}

static s16_t phasestatusgrouptable_get_value(
  struct snmp_node_instance *cell_instance,
  void *value)
{
  s16_t value_len;
  u32_t i = cell_instance->reference.u32 - 1;

  switch (SNMP_TABLE_GET_COLUMN_FROM_OID(cell_instance->instance_oid.id))
  {
      case 1:
      {
        /* phaseStatusGroupNumber */
        s32_t *v = (s32_t *) value;

        *v = GetAscPhasePtr()->SaStatuses[i].bNumber;
        value_len = sizeof(s32_t);
        break;
      }

      case 2:
      {
        /* phaseStatusGroupReds */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstPhase = i * 8;
        uint8_t bPhaseIdx = 0;
        uint8_t bStatusGroupReds = 0;

        for (bPhaseIdx = bFirstPhase; bPhaseIdx < bFirstPhase + 8; bPhaseIdx++)
        {
          switch (StateCurrentGet())
          {
              case STATES_PHASE:
              {
                if (ProgramCurrentNoGet()
                    && (bPhaseIdx != ProgramCurrentNoGet() - 1))
                {
                  bStatusGroupReds |= (1 << (bPhaseIdx - bFirstPhase));
                }

                break;
              }

              default:
              {
                bStatusGroupReds |= (1 << (bPhaseIdx - bFirstPhase));
                break;
              }
          }
        }

        *v = bStatusGroupReds;
        value_len = sizeof(s32_t);
        break;
      }

      case 3:
      {
        /* phaseStatusGroupYellows */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstPhase = i * 8;
        uint8_t bPhaseIdx = 0;
        uint8_t bStatusGroupYellows = 0;

        for (bPhaseIdx = bFirstPhase; bPhaseIdx < bFirstPhase + 8; bPhaseIdx++)
        {
          switch (StateCurrentGet())
          {
              case STATES_PHASE_TRANSITION:
              {
                if (ProgramCurrentNoGet()
                    && (bPhaseIdx == ProgramCurrentNoGet() - 1))
                {
                  bStatusGroupYellows |= (1 << (bPhaseIdx - bFirstPhase));
                }

                break;
              }
          }
        }

        *v = bStatusGroupYellows;
        value_len = sizeof(s32_t);
        break;
      }

      case 4:
      {
        /* phaseStatusGroupGreens */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstPhase = i * 8;
        uint8_t bPhaseIdx = 0;
        uint8_t bStatusGroupGreens = 0;

        for (bPhaseIdx = bFirstPhase; bPhaseIdx < bFirstPhase + 8; bPhaseIdx++)
        {
          switch (StateCurrentGet())
          {
              case STATES_PHASE:
              {
                if (ProgramCurrentNoGet()
                    && (bPhaseIdx == ProgramCurrentNoGet() - 1))
                {
                  bStatusGroupGreens |= (1 << (bPhaseIdx - bFirstPhase));
                }

                break;
              }
          }
        }

        *v = bStatusGroupGreens;
        value_len = sizeof(s32_t);
        break;
      }

      case 5:
      {
        /* phaseStatusGroupDontWalks */
        s32_t *v = (s32_t *) value;

        *v = GetAscPhasePtr()->SaStatuses[i].bDontWalks;
        value_len = sizeof(s32_t);
        break;
      }

      case 6:
      {
        /* phaseStatusGroupPedClears */
        s32_t *v = (s32_t *) value;

        *v = GetAscPhasePtr()->SaStatuses[i].bPedCalls;
        value_len = sizeof(s32_t);
        break;
      }

      case 7:
      {
        /* phaseStatusGroupWalks */
        s32_t *v = (s32_t *) value;

        *v = GetAscPhasePtr()->SaStatuses[i].bWalks;
        value_len = sizeof(s32_t);
        break;
      }

      case 8:
      {
        /* phaseStatusGroupVehCalls */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstPhase = i * 8;
        uint8_t bPhaseIdx = 0;
        uint8_t bStatusGroupVehCalls = 0;

        for (bPhaseIdx = bFirstPhase; bPhaseIdx < bFirstPhase + 8; bPhaseIdx++)
        {
          switch (StateCurrentGet())
          {
              case STATES_PHASE:
              {
                uint8_t bCurPhaseNo = ProgramCurrentNoGet();

                if (bCurPhaseNo && (bPhaseIdx == bCurPhaseNo - 1))
                {
                  uint8_t bSGIdx = 0;

                  for (bSGIdx = 0; bSGIdx < SGTotalGet(); bSGIdx++)
                  {
                    if (PhaseHasSG(bPhaseIdx, bSGIdx))
                    {
                      if (GetSRuntimePtr()->SaDetectorRuntimes[bSGIdx].
                          bDemandCntInGreen || GetSRuntimePtr()
                          ->SaDetectorRuntimes[bSGIdx].bDemandCntInRed)
                      {
                        bStatusGroupVehCalls |= (1 <<
                                                 (bPhaseIdx - bFirstPhase));
                      }
                    }
                  }
                }

                break;
              }
          }
        }

        *v = bStatusGroupVehCalls;
        value_len = sizeof(s32_t);
        break;
      }

      case 9:
      {
        /* phaseStatusGroupPedCalls */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstPhase = i * 8;
        uint8_t bPhaseIdx = 0;
        uint8_t bStatusGroupPedCalls = 0;

        for (bPhaseIdx = bFirstPhase; bPhaseIdx < bFirstPhase + 8; bPhaseIdx++)
        {
          switch (StateCurrentGet())
          {
              case STATES_PHASE:
              {
                uint8_t bCurPhaseNo = ProgramCurrentNoGet();

                if (bCurPhaseNo && (bPhaseIdx == bCurPhaseNo - 1))
                {
                  uint8_t bSGIdx = 0;

                  for (bSGIdx = 0; bSGIdx < SGTotalGet(); bSGIdx++)
                  {
                    if (PhaseHasSG(bPhaseIdx, bSGIdx))
                    {
                      if (GetSRuntimePtr()->SaSGIORuntime[bSGIdx].
                          bDemandCntInGreen
                          || GetSRuntimePtr()->SaSGIORuntime[bSGIdx]
                          .bDemandCntInRed)
                      {
                        bStatusGroupPedCalls |= (1 <<
                                                 (bPhaseIdx - bFirstPhase));
                      }
                    }
                  }
                }

                break;
              }
          }
        }

        *v = bStatusGroupPedCalls;
        value_len = sizeof(s32_t);
        break;
      }

      case 10:
      {
        /* phaseStatusGroupPhaseOns */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstPhase = i * 8;
        uint8_t bPhaseIdx = 0;
        uint8_t bStatusGroupPhaseOns = 0;

        for (bPhaseIdx = bFirstPhase; bPhaseIdx < bFirstPhase + 8; bPhaseIdx++)
        {
          switch (StateCurrentGet())
          {
              case STATES_PHASE:
              {
                if (ProgramCurrentNoGet()
                    && (bPhaseIdx == ProgramCurrentNoGet() - 1))
                {
                  bStatusGroupPhaseOns |= (1 << (bPhaseIdx - bFirstPhase));
                }

                break;
              }
          }
        }

        *v = bStatusGroupPhaseOns;
        value_len = sizeof(s32_t);
        break;
      }

      case 11:
      {
        /* phaseStatusGroupPhaseNexts */
        s32_t *v = (s32_t *) value;

        *v = GetAscPhasePtr()->SaStatuses[i].bPhaseNexts;
        value_len = sizeof(s32_t);
        break;
      }

      default:
      {
        LWIP_DEBUGF(SNMP_MIB_DEBUG,
                    ("phasestatusgrouptable_get_value(): unknown id: %"S32_F
                     "\n",
                     SNMP_TABLE_GET_COLUMN_FROM_OID(
                       cell_instance->instance_oid.id)));
        value_len = 0;
        break;
      }
  } /* switch */

  return value_len;
} /* phasestatusgrouptable_get_value */

