static snmp_err_t vehicledetectorstatusgrouptable_get_instance(
  const u32_t *column,
  const u32_t *row_oid,
  u8_t row_oid_len,
  struct
  snmp_node_instance *cell_instance)
{
  u8_t i;

  LWIP_UNUSED_ARG(column);

  /* check if incoming OID length and if values are in plausible range */
  if (!snmp_oid_in_range(row_oid,
                         row_oid_len,
                         vehicle_detector_status_group_table_oid_ranges,
                         LWIP_ARRAYSIZE(
                           vehicle_detector_status_group_table_oid_ranges)))
  {
    return SNMP_ERR_NOSUCHINSTANCE;
  }

  /* get netif index from incoming OID */
  i = row_oid[0];

  /* find netif with index */
  if (i <= INPUTS_DETECTOR_STATUS_GROUPS_MAX)
  {
    cell_instance->reference.u32 = (u32_t) (i);

    return SNMP_ERR_NOERROR;
  }

  return SNMP_ERR_NOSUCHINSTANCE;
}

static snmp_err_t vehicledetectorstatusgrouptable_get_next_instance(
  const u32_t *column,
  struct snmp_obj_id *row_oid,
  struct
  snmp_node_instance *cell_instance)
{
  struct snmp_next_oid_state state;
  u32_t result_temp[LWIP_ARRAYSIZE(
                      vehicle_detector_status_group_table_oid_ranges)];
  size_t i;

  LWIP_UNUSED_ARG(column);

  /* init struct to search next oid */
  snmp_next_oid_init(&state, row_oid->id, row_oid->len, result_temp,
                     LWIP_ARRAYSIZE(
                       vehicle_detector_status_group_table_oid_ranges));

  /* iterate over all possible OIDs to find the next one */
  for (i = 1; i <= INPUTS_DETECTOR_STATUS_GROUPS_MAX; i++)
  {
    u32_t test_oid[LWIP_ARRAYSIZE(
                     vehicle_detector_status_group_table_oid_ranges)];

    test_oid[0] = i;

    /* check generated OID: is it a candidate for the next one? */
    snmp_next_oid_check(&state, test_oid,
                        LWIP_ARRAYSIZE(
                          vehicle_detector_status_group_table_oid_ranges),
                        (void *) i);
  }

  /* did we find a next one? */
  if (state.status == SNMP_NEXT_OID_STATUS_SUCCESS)
  {
    snmp_oid_assign(row_oid, state.next_oid, state.next_oid_len);
    cell_instance->reference.u32 = LWIP_CONST_CAST(u32_t, state.reference);

    return SNMP_ERR_NOERROR;
  }

  /* not found */
  return SNMP_ERR_NOSUCHINSTANCE;
}

static s16_t vehicledetectorstatusgrouptable_get_value(
  struct snmp_node_instance *cell_instance,
  void *value)
{
  s16_t value_len;
  s32_t i = cell_instance->reference.u32 - 1;

  switch (SNMP_TABLE_GET_COLUMN_FROM_OID(cell_instance->instance_oid.id))
  {
      case 1:
      {
        /* vehicleDetectorStatusGroupNumber */
        s32_t *v = (s32_t *) value;

        *v = i + 1;
        value_len = sizeof(s32_t);
        break;
      }

      case 2:
      {
        /* vehicleDetectorStatusGroupActive */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstLD = i * 8;
        uint8_t bLDIdx = 0;
        uint8_t bStatusGroupActive = 0;

        for (bLDIdx = bFirstLD; bLDIdx < bFirstLD + 8; bLDIdx++)
        {
          if (!GetBitValue(SaCanDetectorIOInputs[bLDIdx
                                                 / IO_INPUTS_DETECTOR_MAX].
                           sLoopEmptyStates,
                           bLDIdx % IO_INPUTS_DETECTOR_MAX))
          {
            bStatusGroupActive |= (1 << (bLDIdx - bFirstLD));
          }
        }

        *v = bStatusGroupActive;
        value_len = sizeof(s32_t);
        break;
      }

      case 3:
      {
        /* vehicleDetectorStatusGroupAlarms */
        s32_t *v = (s32_t *) value;
        uint8_t bFirstLD = i * 8;
        uint8_t bLDIdx = 0;
        uint8_t bStatusGroupAlarms = 0;

        for (bLDIdx = bFirstLD; bLDIdx < bFirstLD + 8; bLDIdx++)
        {
          if (!GetBitValue(SaCanDetectorIOInputs[bLDIdx
                                                 / IO_INPUTS_DETECTOR_MAX].
                           sLoopSafeStates,
                           bLDIdx % IO_INPUTS_DETECTOR_MAX))
          {
            bStatusGroupAlarms |= (1 << (bLDIdx - bFirstLD));
          }
        }

        *v = bStatusGroupAlarms;
        value_len = sizeof(s32_t);
        break;
      }

      default:
      {
        LWIP_DEBUGF(SNMP_MIB_DEBUG,
                    (
                      "vehicledetectorstatusgrouptable_get_value(): unknown id: %"S32_F
                      "\n",
                      SNMP_TABLE_GET_COLUMN_FROM_OID(
                        cell_instance->instance_oid.id)));
        value_len = 0;
        break;
      }
  } /* switch */

  return value_len;
} /* vehicledetectorstatusgrouptable_get_value */

