static snmp_err_t cabinetenvirondevicestable_get_instance(const u32_t *column,
                                                          const u32_t *row_oid,
                                                          u8_t row_oid_len,
                                                          struct
                                                          snmp_node_instance *
                                                          cell_instance)
{
  u8_t i, j;

  LWIP_UNUSED_ARG(column);

  /* check if incoming OID length and if values are in plausible range */
  if (!snmp_oid_in_range(row_oid,
                         row_oid_len,
                         cabinet_environment_devices_table_oid_ranges,
                         LWIP_ARRAYSIZE(
                           cabinet_environment_devices_table_oid_ranges)))
  {
    return SNMP_ERR_NOSUCHINSTANCE;
  }

  i = row_oid[0];
  j = row_oid[1];

  if (i <= LWIP_ARRAYSIZE(GetASCCabinetEnvironmentPtr()->SaaEnvironmentDevices))
  {
    if (j
        <= LWIP_ARRAYSIZE(
          GetASCCabinetEnvironmentPtr()->SaaEnvironmentDevices[i]))
    {
      return SNMP_ERR_NOERROR;
    }
  }

  return SNMP_ERR_NOSUCHINSTANCE;
}

static snmp_err_t cabinetenvirondevicestable_get_next_instance(
  const u32_t *column,
  struct snmp_obj_id *row_oid,
  struct
  snmp_node_instance *cell_instance)
{
  struct snmp_next_oid_state state;
  u32_t result_temp[LWIP_ARRAYSIZE(
                      cabinet_environment_devices_table_oid_ranges)];
  u8_t i;
  u8_t j;

  LWIP_UNUSED_ARG(column);

  /* init struct to search next oid */
  snmp_next_oid_init(&state,
                     row_oid->id,
                     row_oid->len,
                     result_temp,
                     LWIP_ARRAYSIZE(
                       cabinet_environment_devices_table_oid_ranges));

  /* iterate over all possible OIDs to find the next one */
  for (i = 1;
       i
       <= LWIP_ARRAYSIZE(GetASCCabinetEnvironmentPtr()->SaaEnvironmentDevices);
       i++)
  {
    for (j = 1;
         j
         <= LWIP_ARRAYSIZE(
           GetASCCabinetEnvironmentPtr()->SaaEnvironmentDevices[i]);
         j++)
    {
      u32_t test_oid[LWIP_ARRAYSIZE(
                       cabinet_environment_devices_table_oid_ranges)];

      test_oid[0] = i;
      test_oid[1] = j;
      snmp_next_oid_check(&state, test_oid,
                          LWIP_ARRAYSIZE(
                            cabinet_environment_devices_table_oid_ranges),
                          NULL);
    }
  }

  /* did we find a next one? */
  if (state.status == SNMP_NEXT_OID_STATUS_SUCCESS)
  {
    snmp_oid_assign(row_oid, state.next_oid, state.next_oid_len);

    return SNMP_ERR_NOERROR;
  }

  /* not found */
  return SNMP_ERR_NOSUCHINSTANCE;
}

