/* --- rsuAsc 1.3.6.1.4.1.1206.4.2.1.1.17 ----------------------------------------------------- */
/* --- asc  ----------------------------------------------------- */
static s16_t ascblock_scalars_get_value(
  const struct snmp_scalar_array_node_def *node,
  void *value)
{
  s16_t value_len;

  switch (node->oid)
  {
      case 1:
      {
        /* ascBlockGetControl */
        value_len = sizeof(GetAscBlockPtr()->baGetControl);
        if (value_len <= SNMP_MAX_VALUE_SIZE)
        {
          memcpy(value, GetAscBlockPtr()->baGetControl, value_len);
        }
        else
        {
          value_len = 0;
        }

        break;
      }

      case 2:
      {
        /* ascBlockData */
        value_len = sizeof(GetAscBlockPtr()->baData);
        if (value_len <= SNMP_MAX_VALUE_SIZE)
        {
          memcpy(value,
                 GetAscBlockPtr()->baData,
                 value_len);
        }
        else
        {
          value_len = 0;
        }

        break;
      }

      case 3:
      {
        /* ascBlockErrorStatus */
        s32_t *v = (s32_t *) value;

        *v = GetAscBlockPtr()->sErrorStatus;
        value_len = sizeof(s32_t);
        break;
      }

      default:
      {
        LWIP_DEBUGF(SNMP_MIB_DEBUG,
                    ("ascblock_scalars_get_value(): unknown id: %"S32_F"\n",
                     node->oid));
        value_len = 0;
        break;
      }
  } /* switch */

  return value_len;
} /* ascblock_scalars_get_value */

static snmp_err_t ascblock_scalars_set_test(
  const struct snmp_scalar_array_node_def *node,
  u16_t len,
  void *value)
{
  snmp_err_t err = SNMP_ERR_WRONGVALUE;

  switch (node->oid)
  {
      case 1:
      {
        /* ascBlockGetControl */
        u8_t *v = (u8_t *) value;

        if (((len >= 4) && (len <= 12)))
        {
          err = SNMP_ERR_NOERROR;
        }

        LWIP_UNUSED_ARG(v);
        break;
      }

      case 2:
      {
        /* ascBlockData */
        u8_t *v = (u8_t *) value;

        if (((len >= 6) && (len <= 65535)))
        {
          err = SNMP_ERR_NOERROR;
        }

        LWIP_UNUSED_ARG(v);
        break;
      }

      default:
      {
        LWIP_DEBUGF(SNMP_MIB_DEBUG,
                    ("ascblock_scalars_set_test(): unknown id: %"S32_F"\n",
                     node->oid));
        break;
      }
  }

  return err;
} /* ascblock_scalars_set_test */

static snmp_err_t ascblock_scalars_set_value(
  const struct snmp_scalar_array_node_def *node,
  u16_t len,
  void *value)
{
  snmp_err_t err = SNMP_ERR_NOERROR;

  LWIP_UNUSED_ARG(len);
  switch (node->oid)
  {
      case 1:
      {
        /* ascBlockGetControl */
        memset(GetAscBlockPtr()->baGetControl, 0,
               sizeof(GetAscBlockPtr()->baGetControl));
        memcpy(GetAscBlockPtr()->baGetControl, value, len);
        break;
      }

      case 2:
      {
        /* ascBlockData */
        memset(GetAscBlockPtr()->baData, 0, sizeof(GetAscBlockPtr()->baData));
        memcpy(GetAscBlockPtr()->baData, value, len);
        break;
      }

      default:
      {
        LWIP_DEBUGF(SNMP_MIB_DEBUG,
                    ("ascblock_scalars_set_value(): unknown id: %"S32_F"\n",
                     node->oid));
        break;
      }
  }

  return err;
}

